// Builds the ACM USTP homepage in the ACM-WEBSITE-CONCEPT-DESIGN file around the existing
// "Sponsors — Logo wall" frame. Safe to re-run: the previous build is replaced, the logo wall is kept.
const IMAGES = { logo: '', poster: '' };

const hex = h => ({ r: parseInt(h.slice(1, 3), 16) / 255, g: parseInt(h.slice(3, 5), 16) / 255, b: parseInt(h.slice(5, 7), 16) / 255 });
const solid = (h, opacity = 1) => ({ type: 'SOLID', color: hex(h), opacity });
const K = { bg: '#05070a', surface: '#0b1020', border: '#1f2a3d', accent: '#6463c8', cyan: '#3baede', text: '#f5f7ff', soft: '#d7e0f0', muted: '#8ea0c7', muted2: '#7b879c', planet: '#05aed5' };
const PAD = 120, CONTENT = 1200;
const PAGE_NAME = 'ACM USTP — Homepage', COMPS_NAME = 'Homepage components', WALL_NAME = 'Sponsors — Logo wall';

const autoLayout = (dir, props = {}) => {
  const f = figma.createFrame();
  f.layoutMode = dir; f.primaryAxisSizingMode = 'AUTO'; f.counterAxisSizingMode = 'AUTO'; f.fills = [];
  return Object.assign(f, props);
};
const text = (chars, family, style, size, color, width) => {
  const t = figma.createText(); t.fontName = { family, style }; t.characters = chars; t.fontSize = size; t.fills = [solid(color)];
  if (width) { t.resize(width, t.height); t.textAutoResize = 'HEIGHT'; }
  return t;
};
const glow = (h, a, r) => ({ type: 'DROP_SHADOW', color: Object.assign(hex(h), { a }), offset: { x: 0, y: 0 }, radius: r, spread: 0, visible: true, blendMode: 'NORMAL' });
const topBorder = n => { n.strokes = [solid(K.border)]; n.strokeTopWeight = 1; n.strokeLeftWeight = n.strokeRightWeight = n.strokeBottomWeight = 0; };
const add = (parent, n, fill = true) => { parent.appendChild(n); if (fill) n.layoutSizingHorizontal = 'FILL'; return n; };
const imageFill = (b64, opacity = 1) => ({ type: 'IMAGE', imageHash: figma.createImage(figma.base64Decode(b64)).hash, scaleMode: 'FILL', opacity });

async function main() {
  const page = figma.currentPage;
  const wall = page.findOne(n => n.type === 'FRAME' && n.name === WALL_NAME);
  if (!wall) throw new Error(`No frame named "${WALL_NAME}" on this page`);
  // Re-run: rescue the logo wall out of the old build before removing it
  for (const old of page.children.filter(n => n.name === PAGE_NAME || n.name === COMPS_NAME)) {
    if (wall.parent === old) { const { x, y } = old; page.appendChild(wall); wall.x = x; wall.y = y; }
    old.remove();
  }
  await Promise.all([['Barlow Semi Condensed', 'Medium'], ['Barlow Semi Condensed', 'SemiBold'], ['Barlow Semi Condensed', 'Bold'], ['Figtree', 'Regular'], ['Figtree', 'Medium'], ['Figtree', 'SemiBold'], ['JetBrains Mono', 'Regular']]
    .map(([family, style]) => figma.loadFontAsync({ family, style })));

  // Components, beside the Logo tile set
  const tileSet = page.findOne(n => n.type === 'COMPONENT_SET' && n.name === 'Logo tile');
  const comps = autoLayout('HORIZONTAL', { name: COMPS_NAME, itemSpacing: 40, paddingLeft: 40, paddingRight: 40, paddingTop: 40, paddingBottom: 40 });
  comps.fills = [solid(K.bg)];
  comps.x = tileSet ? tileSet.x + tileSet.width + 80 : wall.x; comps.y = tileSet ? tileSet.y : wall.y - 600;

  const card = figma.createComponent();
  card.name = 'Card'; card.layoutMode = 'VERTICAL'; card.primaryAxisSizingMode = 'AUTO'; card.counterAxisSizingMode = 'FIXED'; card.resize(380, 100);
  card.itemSpacing = 12; card.paddingLeft = card.paddingRight = card.paddingTop = card.paddingBottom = 40;
  card.fills = [solid(K.surface, .7)]; card.strokes = [solid(K.border)];
  const cTop = text('NOV 15, 2026', 'Figtree', 'SemiBold', 12, K.cyan); cTop.letterSpacing = { unit: 'PERCENT', value: 8 }; cTop.name = 'Top';
  const cTitle = text('Card title', 'Barlow Semi Condensed', 'Medium', 24, K.text); cTitle.name = 'Title';
  const cBody = text('Card body text.', 'Figtree', 'Regular', 16, K.muted); cBody.name = 'Body'; cBody.lineHeight = { unit: 'PERCENT', value: 160 };
  for (const t of [cTop, cTitle, cBody]) { card.appendChild(t); t.layoutSizingHorizontal = 'FILL'; t.textAutoResize = 'HEIGHT'; }
  const pTop = card.addComponentProperty('Top', 'TEXT', 'NOV 15, 2026'), pTitle = card.addComponentProperty('Title', 'TEXT', 'Card title'), pBody = card.addComponentProperty('Body', 'TEXT', 'Card body text.');
  cTop.componentPropertyReferences = { characters: pTop }; cTitle.componentPropertyReferences = { characters: pTitle }; cBody.componentPropertyReferences = { characters: pBody };
  card.description = 'About pillars and Events. Top = icon or date.';
  comps.appendChild(card);

  const off = figma.createComponent();
  off.name = 'Officer'; off.layoutMode = 'VERTICAL'; off.primaryAxisSizingMode = 'AUTO'; off.counterAxisSizingMode = 'FIXED'; off.resize(276, 100);
  off.counterAxisAlignItems = 'CENTER'; off.itemSpacing = 8; off.paddingLeft = off.paddingRight = off.paddingTop = off.paddingBottom = 40;
  off.fills = [solid(K.surface, .7)]; off.strokes = [solid(K.border)];
  const av = autoLayout('HORIZONTAL', { name: 'Avatar', primaryAxisAlignItems: 'CENTER', counterAxisAlignItems: 'CENTER' });
  av.primaryAxisSizingMode = 'FIXED'; av.counterAxisSizingMode = 'FIXED'; av.resize(96, 96); av.cornerRadius = 48;
  av.fills = [{ type: 'GRADIENT_RADIAL', gradientTransform: [[1, 0, -.2], [0, 1, -.2]], gradientStops: [{ position: 0, color: Object.assign(hex(K.accent), { a: 1 }) }, { position: 1, color: Object.assign(hex(K.surface), { a: 1 }) }] }];
  av.effects = [glow(K.accent, .35, 30)];
  const ini = text('JD', 'Figtree', 'SemiBold', 22, K.text); ini.name = 'Initials'; av.appendChild(ini);
  const oName = text('Juan Dela Cruz', 'Barlow Semi Condensed', 'Medium', 24, K.text); oName.name = 'Name';
  const oRole = text('President', 'Figtree', 'Regular', 16, K.muted); oRole.name = 'Role';
  for (const n of [av, oName, oRole]) off.appendChild(n);
  const pI = off.addComponentProperty('Initials', 'TEXT', 'JD'), pN = off.addComponentProperty('Name', 'TEXT', 'Juan Dela Cruz'), pR = off.addComponentProperty('Role', 'TEXT', 'President');
  ini.componentPropertyReferences = { characters: pI }; oName.componentPropertyReferences = { characters: pN }; oRole.componentPropertyReferences = { characters: pR };
  comps.appendChild(off);

  const planet = figma.createComponent(); planet.name = 'Planet marker'; planet.resize(32, 32); planet.fills = [];
  const ring = figma.createRectangle(); ring.name = 'Bracket'; ring.resize(32, 32); ring.fills = []; ring.strokes = [solid(K.planet, .6)]; ring.dashPattern = [6, 20];
  const box = figma.createRectangle(); box.name = 'Box'; box.resize(18, 18); box.x = 7; box.y = 7; box.fills = [solid(K.planet, .15)]; box.strokes = [solid(K.planet)]; box.effects = [glow(K.planet, .5, 12)];
  const core = figma.createRectangle(); core.name = 'Core'; core.resize(8, 8); core.x = 12; core.y = 12; core.fills = [solid(K.planet)];
  for (const n of [ring, box, core]) planet.appendChild(n);
  planet.description = 'Orbiting marker on the hero black hole; shows a name label on hover.';
  comps.appendChild(planet);

  // Page wrapper takes the logo wall's spot on the canvas
  const home = autoLayout('VERTICAL', { name: PAGE_NAME });
  home.resize(1440, 100); home.counterAxisSizingMode = 'FIXED'; home.primaryAxisSizingMode = 'AUTO';
  home.fills = [solid(K.bg)]; home.clipsContent = true; home.x = wall.x; home.y = wall.y;

  // Navbar
  const nav = add(home, autoLayout('HORIZONTAL', { name: 'Navbar', primaryAxisAlignItems: 'SPACE_BETWEEN', counterAxisAlignItems: 'CENTER', paddingLeft: PAD, paddingRight: PAD }));
  nav.counterAxisSizingMode = 'FIXED'; nav.resize(1440, 88);
  nav.fills = [solid(K.bg, .72)]; nav.strokes = [solid(K.border)]; nav.strokeBottomWeight = 1; nav.strokeTopWeight = nav.strokeLeftWeight = nav.strokeRightWeight = 0;
  const brand = add(nav, autoLayout('HORIZONTAL', { name: 'Brand', itemSpacing: 13, counterAxisAlignItems: 'CENTER' }), false);
  const logo = figma.createRectangle(); logo.name = 'acm-logo'; logo.resize(108, 36); logo.fills = [imageFill(IMAGES.logo)]; brand.appendChild(logo);
  const wm = add(brand, autoLayout('VERTICAL', { name: 'Wordmark', itemSpacing: 4 }), false);
  wm.appendChild(text('ACM USTP', 'Barlow Semi Condensed', 'SemiBold', 24, K.text));
  const small = text('STUDENT CHAPTER', 'Figtree', 'Regular', 9, K.muted); small.letterSpacing = { unit: 'PERCENT', value: 50 }; wm.appendChild(small);
  const links = add(nav, autoLayout('HORIZONTAL', { name: 'Links', itemSpacing: 34, counterAxisAlignItems: 'CENTER' }), false);
  for (const l of ['About Us', 'Events', 'Sponsors', 'Team']) { const t = text(l, 'Figtree', 'Regular', 14, K.soft); t.opacity = .8; links.appendChild(t); }
  const btn = add(links, autoLayout('HORIZONTAL', { name: 'Button / Join us', itemSpacing: 26, paddingLeft: 22, paddingRight: 22, counterAxisAlignItems: 'CENTER' }), false);
  btn.counterAxisSizingMode = 'FIXED'; btn.resize(btn.width, 50); btn.fills = [solid(K.accent)];
  btn.appendChild(text('Join us', 'Figtree', 'Medium', 13, K.text)); btn.appendChild(text('↗', 'Figtree', 'Medium', 16, K.text));

  // Hero
  const label = (chars, hud) => {
    const row = autoLayout('HORIZONTAL', { name: 'Section label', itemSpacing: 12, counterAxisAlignItems: 'CENTER' });
    const line = figma.createRectangle(); line.resize(24, 1); line.fills = [solid(K.accent)]; row.appendChild(line);
    const t = hud ? text(chars + '_', 'JetBrains Mono', 'Regular', 11, K.cyan) : text(chars.toUpperCase(), 'Figtree', 'SemiBold', 11, K.text);
    t.letterSpacing = { unit: 'PERCENT', value: 8 }; row.appendChild(t); return row;
  };
  const hero = add(home, autoLayout('VERTICAL', { name: 'Hero', counterAxisAlignItems: 'MAX' }));
  const copy = add(hero, autoLayout('VERTICAL', { name: 'Hero copy', itemSpacing: 28, paddingLeft: PAD, paddingRight: PAD, paddingTop: 120, paddingBottom: 96 }));
  copy.appendChild(label('THIS IS ACM USTP', true));
  const h1 = text('Exploring the universe\nof computing.', 'Barlow Semi Condensed', 'Bold', 120, K.text);
  h1.lineHeight = { unit: 'PERCENT', value: 108 }; h1.name = 'H1';
  const ci = h1.characters.indexOf('computing.'); h1.setRangeFills(ci, ci + 10, [solid(K.cyan)]);
  add(copy, h1); h1.textAutoResize = 'HEIGHT';
  const row = add(copy, autoLayout('HORIZONTAL', { name: 'Intro row', primaryAxisAlignItems: 'MAX', paddingTop: 24 }));
  const welcome = add(row, autoLayout('VERTICAL', { name: 'Welcome', itemSpacing: 26 }), false);
  const intro = text('A community of student developers, designers, and innovators at the University of Science and Technology of Southern Philippines. Welcome aboard.', 'Figtree', 'Medium', 18, K.text, 560);
  intro.lineHeight = { unit: 'PERCENT', value: 160 }; welcome.appendChild(intro);
  const anchor = autoLayout('HORIZONTAL', { name: 'Anchor', itemSpacing: 12 });
  anchor.appendChild(text('Get to know us', 'Figtree', 'SemiBold', 14, K.text)); anchor.appendChild(text('↓', 'Figtree', 'SemiBold', 14, K.text));
  welcome.appendChild(anchor);
  const vid = figma.createFrame(); vid.name = 'Hero video (poster)'; vid.resize(1325, 745); vid.fills = [solid(K.bg)]; vid.clipsContent = true; hero.appendChild(vid);
  const poster = figma.createRectangle(); poster.name = 'Poster image'; poster.resize(1325, 745); poster.fills = [imageFill(IMAGES.poster, .62)]; vid.appendChild(poster);
  const DISK = [[297, 377], [662, 294], [903, 140], [1132, 301], [993, 394], [587, 383]];
  DISK.forEach(([x, y], i) => { const p = planet.createInstance(); vid.appendChild(p); p.x = x * 1325 / 1280 - 16; p.y = y * 745 / 720 - 16; p.name = `Planet ${i + 1}`; });

  // Sections
  const section = (name, lbl, title, lead, extra) => {
    const s = autoLayout('VERTICAL', { name, paddingLeft: PAD, paddingRight: PAD, paddingTop: 140, paddingBottom: 140 });
    topBorder(s); add(home, s);
    const l = label(lbl); l.paddingBottom = 20; s.appendChild(l);
    const t = text(title, 'Barlow Semi Condensed', 'Medium', 72, K.text); t.lineHeight = { unit: 'PERCENT', value: 108 }; s.appendChild(t);
    for (const [p, size, color, gap] of [[lead, 18, K.soft, 20], [extra, 16, K.muted, 16]]) if (p) {
      const sp = figma.createFrame(); sp.name = 'gap'; sp.resize(1, gap); sp.fills = []; s.appendChild(sp);
      const pt = text(p, 'Figtree', 'Regular', size, color, 640); pt.lineHeight = { unit: 'PERCENT', value: 160 }; s.appendChild(pt);
    }
    return s;
  };
  const grid = (s, items, cols, make) => {
    const g = add(s, autoLayout('HORIZONTAL', { name: 'Grid', itemSpacing: 32, paddingTop: 56 })); g.layoutWrap = 'WRAP'; g.counterAxisSpacing = 32;
    const w = (CONTENT - 32 * (cols - 1)) / cols;
    for (const it of items) { const n = make(it); g.appendChild(n); n.resize(w, n.height); }
  };
  const mkCard = ([top, title, body]) => { const c = card.createInstance(); c.setProperties({ [pTop]: top, [pTitle]: title, [pBody]: body }); return c; };

  const about = section('About', 'Who we are', 'About Us', 'ACM USTP brings together students passionate about computing to grow skills and lead in tech.',
    "Placeholder: a second paragraph on the chapter's mission, history, and what members get out of joining.");
  grid(about, [['🛰️', 'Learn', 'Workshops and study jams on modern tech.'], ['🌌', 'Connect', 'Meet peers, alumni, and industry mentors.'], ['🚀', 'Build', 'Hackathons and projects that solve real problems.'], ['🪐', 'Lead', 'Placeholder: run a project, mentor juniors, or join the officer track.']], 4, mkCard);

  const events = section('Events', 'Mission log', 'Upcoming Events');
  grid(events, [['NOV 15, 2026', 'Web Dev Bootcamp', 'Hands-on HTML, CSS, and JavaScript.'], ['DEC 06, 2026', 'CodeFest Hackathon', '24-hour build challenge for all year levels.'], ['JAN 20, 2027', 'Tech Talk Series', 'Industry speakers on AI and cloud.'],
    ['FEB 14, 2027', 'Placeholder Event', 'Short description of the event goes here.'], ['MAR 08, 2027', 'Placeholder Event', 'Short description of the event goes here.'], ['APR 22, 2027', 'Placeholder Event', 'Short description of the event goes here.']], 3, mkCard);

  // The existing logo wall slots in after Events
  home.appendChild(wall); wall.layoutSizingHorizontal = 'FILL';

  const team = section('Team', 'The crew', 'Meet the Team');
  grid(team, [['Juan Dela Cruz', 'President'], ['Maria Santos', 'Vice President'], ['Jose Reyes', 'Secretary'], ['Ana Garcia', 'Treasurer'], ['Placeholder Name', 'Auditor'], ['Placeholder Name', 'PRO'], ['Placeholder Name', 'Tech Lead'], ['Placeholder Name', 'Events Lead']], 4,
    ([name, role]) => { const o = off.createInstance(); o.setProperties({ [pI]: name.split(' ').map(w => w[0]).slice(0, 2).join(''), [pN]: name, [pR]: role }); return o; });

  const contact = section('Contact', 'Open a channel', 'Get in Touch', 'Want to join or partner with us? Send a message.');
  const form = add(contact, autoLayout('VERTICAL', { name: 'Form', itemSpacing: 16, paddingTop: 32 }), false);
  for (const [lbl, h] of [['Name', 48], ['Email', 48], ['Message', 120]]) {
    const f = autoLayout('VERTICAL', { name: lbl, itemSpacing: 6 }); form.appendChild(f);
    f.appendChild(text(lbl, 'Figtree', 'Regular', 13, K.muted));
    const input = figma.createRectangle(); input.name = 'Input'; input.resize(520, h); input.fills = [solid(K.surface)]; input.strokes = [solid(K.border)]; f.appendChild(input);
  }
  const send = autoLayout('HORIZONTAL', { name: 'Button / Send', itemSpacing: 26, paddingLeft: 22, paddingRight: 22, counterAxisAlignItems: 'CENTER' });
  send.counterAxisSizingMode = 'FIXED'; send.resize(send.width, 50); send.fills = [solid(K.accent)]; form.appendChild(send);
  send.appendChild(text('Send transmission', 'Figtree', 'Medium', 13, K.text)); send.appendChild(text('↗', 'Figtree', 'Medium', 16, K.text));

  const foot = add(home, autoLayout('HORIZONTAL', { name: 'Footer', primaryAxisAlignItems: 'CENTER', paddingTop: 32, paddingBottom: 32, paddingLeft: PAD, paddingRight: PAD }));
  topBorder(foot);
  foot.appendChild(text('© 2026 ACM USTP · acm@ustp.edu.ph · Facebook', 'Figtree', 'Regular', 13, K.muted2));

  figma.viewport.scrollAndZoomIntoView([home]);
  return 'Homepage built';
}

main().then(msg => figma.closePlugin(msg), err => figma.closePlugin('Build failed: ' + err.message));
